head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDFIL45203";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — briefDir
// TODO Stage2: 세션 키 실환경 확인(회신 11항 · user-info 계약에 없는 키) — session.user.corpUsrTpCd

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_conds();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil45203.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_corpUsrTpCd", fn: function(){ return (!(String(($c.session.getUserInfo("corpUsrTpCd")) == null ? '' : ($c.session.getUserInfo("corpUsrTpCd"))).length === 0) && $c.session.getUserInfo("corpUsrTpCd") === '11'); } }, { id: "c_if_91", fn: function(){ return ((((dma_kpage.get("list") ?? (() => { throw new Error("unresolved:" + "kpage.list"); })())) && typeof ((dma_kpage.get("list") ?? (() => { throw new Error("unresolved:" + "kpage.list"); })())).getRowCount === 'function' ? ((dma_kpage.get("list") ?? (() => { throw new Error("unresolved:" + "kpage.list"); })())).getRowCount() : ((((dma_kpage.get("list") ?? (() => { throw new Error("unresolved:" + "kpage.list"); })())) == null) ? 0 : (((dma_kpage.get("list") ?? (() => { throw new Error("unresolved:" + "kpage.list"); })())).length || 0))) === 0); } }, { id: "c_when_73", fn: function(){ return (dma_searchFindReq.get("srchFd") === 'brief'); } }, { id: "c_if_120", fn: function(){ return ((((dma_kpage.get("list") ?? (() => { throw new Error("unresolved:" + "kpage.list"); })())) && typeof ((dma_kpage.get("list") ?? (() => { throw new Error("unresolved:" + "kpage.list"); })())).getRowCount === 'function' ? ((dma_kpage.get("list") ?? (() => { throw new Error("unresolved:" + "kpage.list"); })())).getRowCount() : ((((dma_kpage.get("list") ?? (() => { throw new Error("unresolved:" + "kpage.list"); })())) == null) ? 0 : (((dma_kpage.get("list") ?? (() => { throw new Error("unresolved:" + "kpage.list"); })())).length || 0))) === 0); } }, { id: "c_when_98", fn: function(){ return (dma_searchFindReq.get("srchFd") === 'checkPoint'); } }, { id: "c_if_149", fn: function(){ return ((((dma_kpage.get("list") ?? (() => { throw new Error("unresolved:" + "kpage.list"); })())) && typeof ((dma_kpage.get("list") ?? (() => { throw new Error("unresolved:" + "kpage.list"); })())).getRowCount === 'function' ? ((dma_kpage.get("list") ?? (() => { throw new Error("unresolved:" + "kpage.list"); })())).getRowCount() : ((((dma_kpage.get("list") ?? (() => { throw new Error("unresolved:" + "kpage.list"); })())) == null) ? 0 : (((dma_kpage.get("list") ?? (() => { throw new Error("unresolved:" + "kpage.list"); })())).length || 0))) === 0); } }, { id: "c_when_127", fn: function(){ return (dma_searchFindReq.get("srchFd") === 'pressData'); } }, { id: "c_if_178", fn: function(){ return ((((dma_kpage.get("list") ?? (() => { throw new Error("unresolved:" + "kpage.list"); })())) && typeof ((dma_kpage.get("list") ?? (() => { throw new Error("unresolved:" + "kpage.list"); })())).getRowCount === 'function' ? ((dma_kpage.get("list") ?? (() => { throw new Error("unresolved:" + "kpage.list"); })())).getRowCount() : ((((dma_kpage.get("list") ?? (() => { throw new Error("unresolved:" + "kpage.list"); })())) == null) ? 0 : (((dma_kpage.get("list") ?? (() => { throw new Error("unresolved:" + "kpage.list"); })())).length || 0))) === 0); } }, { id: "c_when_156", fn: function(){ return (dma_searchFindReq.get("srchFd") === 'workExample'); } }, { id: "c_if_208", fn: function(){ return ((((dma_kpage.get("list") ?? (() => { throw new Error("unresolved:" + "kpage.list"); })())) && typeof ((dma_kpage.get("list") ?? (() => { throw new Error("unresolved:" + "kpage.list"); })())).getRowCount === 'function' ? ((dma_kpage.get("list") ?? (() => { throw new Error("unresolved:" + "kpage.list"); })())).getRowCount() : ((((dma_kpage.get("list") ?? (() => { throw new Error("unresolved:" + "kpage.list"); })())) == null) ? 0 : (((dma_kpage.get("list") ?? (() => { throw new Error("unresolved:" + "kpage.list"); })())).length || 0))) === 0); } }, { id: "c_when_185", fn: function(){ return (dma_searchFindReq.get("srchFd") === 'issueData'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return "'" + String(dma_combinationReferenceVo.get("kwd")) + "' 검색결과"; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_searchFind_onclick
 * @description 「검색」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_searchFind_onclick = async function(e){
    try {
        await scwin.searchFind()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil45203.btn_searchFind_onclick' }); }
};

/**
 * @method
 * @name grd_kpageList_oncellclick
 * @description grd_kpageList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_kpageList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_kpageList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_kpageList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        await scwin.briefPopView(r["disclsBriefPublIsu"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_kpageList.oncellclick' });
    }
};

