    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_kpageList_5.oncellclick' });
    }
};

/**
 * @method
 * @name krxpage_pagenavigator_215_onclick
 * @description krxpage_pagenavigator_215 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_215_onclick = async function (index) {
    try {
        const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index;
        $c.util.getComponent('dma_searchFindReq').set('pageIndex', pi);
        await scwin.searchFind();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil45203.krxpage_pagenavigator_215_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_searchFind
 * @description search Find 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchFind = async function (action) {
    const sbmOptions = {
        id: "tx_fn_searchFind",
        method: "post",
        action: action ?? "/main/search.do",
        ref: "dma_searchFindReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

