///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_issueDataPopView
 * @description issue Data Pop View 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_issueDataPopView = async function (action) {
    try { return await $c.data.downFile(action ?? "/support/fileDownload.do", "", ($c.util.getComponent("dma_issueDataPopViewReq") ? $c.util.getComponent("dma_issueDataPopViewReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name searchFind
 * @description search Find 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchFind = async function () {
    $c.util.getComponent('dma_searchFindReq').set('pageNum', $c.util.getComponent("dma_searchFindReq").get("pageIndex"));
    $c.util.getComponent("dma_searchFindReq").set("method", 'searchDataReference');
    await scwin.tx_fn_searchFind('/main/search.do');
};

/**
 * @method
 * @name briefPopView
 * @description brief Pop View 처리
 * @param {String} _briefNm _briefNm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.briefPopView = async function (_briefNm) {
    const fileUrl = (String(((dma_pageContext.get("briefDir") ?? "")) == null ? '' : ((dma_pageContext.get("briefDir") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("briefDir") ?? "")) == null ? '' : ((dma_pageContext.get("briefDir") ?? "")))) + '/${briefPrefix}' + _briefNm + '.html';
    const frm = (document.fn_briefPopView || { elements: [] });
    frm.target = '_blank';
    const nr = await scwin.tx_fn_briefPopView(fileUrl);
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/ui/jsp/JLDFIL15600.xml");
    }
};

/**
 * @method
 * @name checkPointPopView
 * @description check Point Pop View 처리
 * @param {*} id id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkPointPopView = async function (id) {
    $c.util.getComponent("dma_searchFindReq").set("contnId", id);
    $c.util.getComponent("dma_searchFindReq").set("method", "popCheckPointView");
    $c.win.openPopup("", { id: "viewCheckPointItem", scrollbars: true, resizable: true, width: "600", height: "500", type: "pageFramePopup" }, {});
    const nr = await scwin.tx_fn_checkPointPopView();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/ui/jsp/JLDFIL16802.xml", { "contnId": id, "method": "popCheckPointView" });
    }
};

/**
 * @method
 * @name pressDataPopView
 * @description press Data Pop View 처리
 * @param {*} id id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.pressDataPopView = async function (id) {
    $c.util.getComponent("dma_searchFindReq").set("contnId", id);
    $c.util.getComponent("dma_searchFindReq").set("method", "popPressDataView");
    $c.win.openPopup("", { id: "viewPressDataItem", scrollbars: true, resizable: false, width: "440", height: "500", type: "pageFramePopup" }, {});
    const nr = await scwin.tx_fn_pressDataPopView();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/ui/jsp/JLDFIL15004.xml", { "contnId": id, "method": "popPressDataView" });
    }
};

