/**
 * @method
 * @name issueDataPopView
 * @description issue Data Pop View 처리
 * @param {String} contnId contnId
 * @param {*} attachSeq attachSeq
 * @param {String} attachFileNm attachFileNm
 * @param {*} wrtDdtm wrtDdtm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.issueDataPopView = async function (contnId, attachSeq, attachFileNm, wrtDdtm) {
    $c.util.getComponent("dma_searchFindReq").set("method", 'searchBbsAttachFile');
    $c.util.getComponent("dma_searchFindReq").set("contnId", contnId);
    $c.util.getComponent('dma_searchFindReq').set('attachSeq', attachSeq);
    $c.util.getComponent('dma_searchFindReq').set('attachFileNm', attachFileNm);
    $c.util.getComponent('dma_searchFindReq').set('wrtDdtm', wrtDdtm);
    await scwin.tx_fn_issueDataPopView('/support/fileDownload.do');
};
